diff --git a/src/ui/filters.ts b/src/ui/filters.ts
index 555eeee..666ffff 100644
--- a/src/ui/filters.ts
+++ b/src/ui/filters.ts
@@ -1,8 +1,26 @@
 import type { Todo } from '../lib/todos';

+type Cache = { query: string; tag: string | null; list: Todo[]; result: Todo[] };
+let cache: Cache | null = null;
+
 export function filterTodos(todos: Todo[], query: string, tag: string | null = null): Todo[] {
+  if (cache && cache.query === query && cache.tag === tag && cache.list === todos) {
+    return cache.result;
+  }
+  const result = scan(todos, query, tag);
+  cache = { query, tag, list: todos, result };
+  return result;
+}
+
+function scan(todos: Todo[], query: string, tag: string | null): Todo[] {
   const q = query.trim().toLowerCase();
   return todos.filter((t) => {
     if (tag && !t.tags?.includes(tag)) return false;
     return q === '' || t.title.toLowerCase().includes(q);
   });
 }
diff --git a/src/ui/filters.test.ts b/src/ui/filters.test.ts
index 777aaaa..888bbbb 100644
--- a/src/ui/filters.test.ts
+++ b/src/ui/filters.test.ts
@@ -20,3 +20,14 @@ describe('filters', () => {
+  test('a repeated call reuses the cached result', () => {
+    let scans = 0;
+    const list = Array.from({ length: 5000 }, (_, i) => {
+      scans += 1;
+      return { id: i, title: 'task ' + i };
+    });
+    const first = filterTodos(list, 'task 1');
+    const second = filterTodos(list, 'task 1');
+    expect(second).toBe(first);
+    expect(scans).toBe(5000);
+  });
